WITH l AS (SELECT DISTINCT li.LOAN_KEY AS k, TO_DATE(li.ORIGINATIONDATE) AS od, ROUND(li.ORIGINALLOANAMOUNT, 2) AS amt FROM EDGAR_DB.PROPERTY_MART.PROPERTY_PERIOD_FACT AS p JOIN EDGAR_DB.PROPERTY_MART.LOAN_ISSUANCE AS li ON p.CIK = li.CIK AND p.ASSETNUMBER = li.ASSETNUMBER WHERE p.COUNTY_FIPS IN ('36005', '36047', '36061', '36081', '36085') AND p.HAS_LOAN = TRUE AND NOT li.ORIGINATIONDATE IS NULL AND NOT li.ORIGINALLOANAMOUNT IS NULL AND ROUND(li.ORIGINALLOANAMOUNT, 2) % 100000 <> 0), b AS (SELECT DISTINCT li.LOAN_KEY AS k, CASE TO_CHAR(p.COUNTY_FIPS) WHEN '36061' THEN 1 WHEN '36005' THEN 2 WHEN '36047' THEN 3 WHEN '36081' THEN 4 WHEN '36085' THEN 5 END AS bo FROM EDGAR_DB.PROPERTY_MART.PROPERTY_PERIOD_FACT AS p JOIN EDGAR_DB.PROPERTY_MART.LOAN_ISSUANCE AS li ON p.CIK = li.CIK AND p.ASSETNUMBER = li.ASSETNUMBER WHERE p.COUNTY_FIPS IN ('36005', '36047', '36061', '36081', '36085') AND p.HAS_LOAN = TRUE), m AS (SELECT DISTINCT DOCUMENT_ID AS d, TO_DATE(RECORDED_DATETIME) AS rd, ROUND(DOCUMENT_AMT, 2) AS amt FROM EDGAR_DB.SOURCE.NYC_ACRIS_REAL_PROPERTY_MASTER_EXT WHERE RELEASE_DT = '2026-08-10' AND RECORDED_BOROUGH IN (1, 2, 3, 4, 5) AND DOC_TYPE IN ('MTGE', 'M&CON', 'CMTG', 'SMTG', 'MMTG', 'SPRD') AND DOCUMENT_AMT BETWEEN 505879.44 AND 135000000 AND TO_DATE(RECORDED_DATETIME) BETWEEN (SELECT MIN(od) FROM l) AND DATEADD(DAY, 45, (SELECT MAX(od) FROM l))), c AS (SELECT DISTINCT l.k, m.d FROM l JOIN m ON m.amt = l.amt AND m.rd BETWEEN l.od AND DATEADD(DAY, 45, l.od) JOIN EDGAR_DB.SOURCE.NYC_ACRIS_REAL_PROPERTY_LEGALS_EXT AS le ON m.d = le.DOCUMENT_ID JOIN b ON l.k = b.k AND le.BOROUGH = b.bo WHERE le.RELEASE_DT = '2026-08-10' AND le.BOROUGH IN (1, 2, 3, 4, 5) AND NOT le.BLOCK IS NULL AND NOT le.LOT IS NULL), cc AS (SELECT k, COUNT(DISTINCT d) AS n FROM c GROUP BY k), a AS (SELECT c.* FROM c JOIN cc USING (k) WHERE n = 1), ab AS (SELECT DISTINCT a.k, TO_CHAR(le.BOROUGH) || LPAD(TO_CHAR(le.BLOCK), 5, '0') || LPAD(TO_CHAR(le.LOT), 4, '0') AS bbl, TO_CHAR(le.BOROUGH) || LPAD(TO_CHAR(le.BLOCK), 5, '0') AS blk, IFF(TRY_TO_NUMBER(le.LOT) BETWEEN 1001 AND 6999, 1, 0) AS co FROM a JOIN EDGAR_DB.SOURCE.NYC_ACRIS_REAL_PROPERTY_LEGALS_EXT AS le ON a.d = le.DOCUMENT_ID WHERE le.RELEASE_DT = '2026-08-10' AND le.BOROUGH IN (1, 2, 3, 4, 5) AND NOT le.BLOCK IS NULL AND NOT le.LOT IS NULL), ps AS (SELECT DISTINCT p.PROPERTY_KEY AS pk, li.LOAN_KEY AS k FROM EDGAR_DB.PROPERTY_MART.PROPERTY_PERIOD_FACT AS p JOIN EDGAR_DB.PROPERTY_MART.LOAN_ISSUANCE AS li ON p.CIK = li.CIK AND p.ASSETNUMBER = li.ASSETNUMBER WHERE p.COUNTY_FIPS IN ('36005', '36047', '36061', '36081', '36085') AND p.HAS_LOAN = TRUE), td AS (SELECT DISTINCT ps.pk, ab.k, ab.bbl, ab.blk, ab.co, d.LATITUDE AS la, d.LONGITUDE AS lo FROM ab JOIN ps USING (k) JOIN EDGAR_DB.PROPERTY_MART.PROPERTY_DIM AS d ON ps.pk = d.PROPERTY_KEY WHERE d.COUNTY_FIPS IN ('36005', '36047', '36061', '36081', '36085') AND NOT d.LATITUDE IS NULL AND NOT d.LONGITUDE IS NULL), pt AS (SELECT g.LATITUDE AS la, g.LONGITUDE AS lo, IFF(COUNT(DISTINCT g.ACCURACY_TYPE) = 1, MIN(g.ACCURACY_TYPE), 'mixed') AS acc, MIN(TO_CHAR(g.SOURCE)) AS source_attribution, MIN(UPPER(TRIM(g.PROPERTY_ADDRESS))) AS asserted_address, MIN(TO_CHAR(g.ASOF)) AS geocode_asof FROM EDGAR_DB.DBT_WRANGLING_EDGAR.WRGL_EDGAR_CMBS_GEOCODES__STRUCTURED AS g JOIN (SELECT DISTINCT la, lo FROM td) AS x ON g.LATITUDE = x.la AND g.LONGITUDE = x.lo WHERE g.COUNTY_FIPS IN ('36005', '36047', '36061', '36081', '36085') GROUP BY g.LATITUDE, g.LONGITUDE), tb AS (SELECT DISTINCT pt.la, pt.lo, pt.acc, pt.source_attribution, pt.asserted_address, pt.geocode_asof, td.k, td.pk AS property_key, td.bbl, td.blk, td.co FROM pt JOIN td ON pt.la = td.la AND pt.lo = td.lo), tp AS (SELECT DISTINCT la, lo, acc, source_attribution, asserted_address, geocode_asof FROM tb), pe AS (SELECT DISTINCT tp.la, tp.lo, REGEXP_REPLACE(TO_CHAR(pl.BBL), '\\.0$', '') AS pb, SUBSTRING(REGEXP_REPLACE(TO_CHAR(pl.BBL), '\\.0$', ''), 1, 6) AS pk, pl.GEOM_GEOG AS pg FROM tp JOIN EDGAR_DB.SOURCE.NYC_DCP_MAPPLUTO_HOT AS pl ON pl.RELEASE = '26v1' AND pl.VARIANT = 'shoreline_clipped' AND pl.BBOX_XMIN <= tp.lo AND pl.BBOX_XMAX >= tp.lo AND pl.BBOX_YMIN <= tp.la AND pl.BBOX_YMAX >= tp.la AND ST_CONTAINS(pl.GEOM_GEOG, ST_MAKEPOINT(tp.lo, tp.la))), tg AS (SELECT tb.la, tb.lo, tb.bbl, pl.GEOM_GEOG AS tg FROM tb LEFT JOIN EDGAR_DB.SOURCE.NYC_DCP_MAPPLUTO_HOT AS pl ON pl.RELEASE = '26v1' AND pl.VARIANT = 'shoreline_clipped' AND REGEXP_REPLACE(TO_CHAR(pl.BBL), '\\.0$', '') = tb.bbl), e AS (SELECT tb.la, tb.lo, tb.acc, tb.source_attribution, tb.asserted_address, tb.geocode_asof, tb.k, tb.property_key, pe.pb, pe.pk, tb.bbl, tb.blk, tb.co, IFF(tg.tg IS NULL, 1, 0) AS miss, ST_DISTANCE(pe.pg, tg.tg) AS pd, ST_DISTANCE(ST_MAKEPOINT(tb.lo, tb.la), tg.tg) AS point_distance FROM tb JOIN pe ON tb.la = pe.la AND tb.lo = pe.lo LEFT JOIN tg ON tb.la = tg.la AND tb.lo = tg.lo AND tb.bbl = tg.bbl), r AS (SELECT la, lo, acc, source_attribution, asserted_address, geocode_asof, MIN(k) AS loan_key, MIN(property_key) AS subject_id, COUNT(DISTINCT bbl) AS tbbl, COUNT(DISTINCT pb) AS pp, COUNT(DISTINCT IFF(pb = bbl, pb, NULL)) AS lh, COUNT(DISTINCT IFF(pk = blk, pk, NULL)) AS bh, MAX(co) AS co, MIN(pd) AS mpd, MIN(point_distance) AS mtd, SUM(miss) AS miss FROM e GROUP BY la, lo, acc, source_attribution, asserted_address, geocode_asof), s AS (SELECT *, CASE WHEN pp > 0 AND lh = 0 AND COALESCE(mtd, mpd) > 500 THEN 'gross_geocode_error_gt500m' WHEN pp > 0 AND lh = 0 AND co = 1 AND miss > 0 THEN 'condo_representation_residue' WHEN pp > 0 AND lh = 0 AND tbbl > 1 AND (mpd <= 25 OR bh > 0) THEN 'assemblage_artifact_neighbor' WHEN pp > 0 AND lh = 0 AND (mpd <= 25 OR bh > 0) THEN 'adjacent_lot_near_miss' WHEN pp > 0 AND lh = 0 THEN 'residual_truth_contamination_suspect' ELSE 'no_failure_class' END AS fc FROM r WHERE pp > 0) SELECT 'e1.gross_class.' || LPAD(TO_CHAR(ROW_NUMBER() OVER (ORDER BY la, lo, acc, loan_key)), 4, '0') AS point_id, subject_id, loan_key, asserted_address, CAST(ROUND(lo * 10000000) AS DECIMAL(18, 0)) AS lon_e7, CAST(ROUND(la * 10000000) AS DECIMAL(18, 0)) AS lat_e7, acc AS accuracy_type, source_attribution, geocode_asof, H3_POINT_TO_CELL_STRING(ST_MAKEPOINT(lo, la), 9) AS home_cell_r9, FALSE AS refuter_fired, 'gross' AS e1_failure_class FROM s WHERE fc = 'gross_geocode_error_gt500m' ORDER BY point_id LIMIT 50
